const steps = Array.isArray(agentOutput.intermediateSteps)
  ? agentOutput.intermediateSteps
  : [];

const handoffStep = steps.find(step => {
  const toolName = String(step?.action?.tool ?? '').replace(/\d+$/, '');
  return toolName === 'Chuyển Nhân viên Tư vấn Xác thực';
});

let source = {};
try {
  source = $('Chuẩn bị đầu vào AI4').first().json;
} catch (e) {
  source = {};
}

return {
  json: {
    handoff_requested: Boolean(handoffStep),
    reason: String(handoffStep?.action?.toolInput?.reason ?? ''),
    priority: String(handoffStep?.action?.toolInput?.priority ?? 'normal'),
    customer_id: String(source.customer_id ?? ''),
    conversation_id: String(source.conversation_id ?? ''),
    chatbot_id: String(source.chatbot_id ?? ''),
    page_id: String(source.page_id ?? '')
  }
};

const j = $json;

const sections = [];

