const viDiacritics=/[ăâđêôơưáàảãạấầẩẫậắằẳẵặéèẻẽẹếềểễệíìỉĩịóòỏõọốồổỗộớờởỡợúùủũụứừửữựýỳỷỹỵ]/i.test(original);
const viMarkers=(lower.match(/\b(?:không|ko|kg|hok|được|dc|mình|mik|bao nhiêu|bn|phần mềm|pm|sản phẩm|sp|anh|chị|em|tôi|bên|giá|dùng|thử|hỗ trợ|cài|bản quyền|với|vs|đâu|nhé|ạ)\b/g)||[]).length;
