const replacements=new Map([['sp','sản phẩm'],['pm','phần mềm'],['ko','không'],['k','không'],['kg','không'],['hok','không'],['dc','được'],['đc','được'],['mk','mình'],['mik','mình'],['bn','bao nhiêu'],['tg','thời gian'],['bh','bao giờ'],['dk','đăng ký'],['sd','sử dụng'],['yc','yêu cầu'],['ib','nhắn tin'],['nt','nhắn tin'],['rep','phản hồi'],['vs','với'],['lic','license'],['ver','version'],['win','windows'],['co','có'],['mo','mở'],['luu','lưu'],['gia','giá'],['tai','tải']]);
